base={'infantry':(25,8,.06,15),'tank':(65,25,.22,20),'air':(90,35,.32,25),'naval':(140,50,.48,30)}
rows=[]
for group,entries in [('infantry',I),('tank',[(*x,'Carro da combattimento') for x in T]),('air',A),('naval',N)]:
 for index,(id,name,origin,maker,role) in enumerate(entries):
  price,power,maintenance,seconds=base[group];delta=index%7-3 if id not in ['arx','abrams','f16','fremm'] else 0
  game={'price':price+delta*(2 if group=='infantry' else 5),'power':max(3,power+delta),'maintenance':round(maintenance+delta*.006,3),'deliverySeconds':seconds+abs(delta)*2,'effectiveness':min(95,55+index%7*5),'resistance':(35 if group in ['infantry','air'] else 65)+index%6*4,'mobility':(65 if group in ['infantry','air'] else 40)+index%7*4,'fictional':True}
  if id=='arx':game.update(effectiveness=55,resistance=35,mobility=65)
  if id=='abrams':game.update(effectiveness=85,resistance=90,mobility=45)
  if id=='f16':game.update(effectiveness=88,resistance=45,mobility=95)
  if id=='fremm':game.update(effectiveness=82,resistance=80,mobility=55)
  description=role+'. '+('Modello storico disponibile come scelta di gioco.' if id in ['chieftain','centurion','challenger1','miragef1'] else 'Capacità rappresentate in forma astratta.')
  if group=='naval':description+=' La classe identifica il progetto, non una singola nave.'
  if id=='type26':description+=' Programma in costruzione: non presentato come già operativo.'
  rows.append({'id':id,'group':group,'identity':{'name':name,'origin':origin,'manufacturer':maker,'role':role,'description':description,'variant':{'arx':'16 pollici','m4':'M4A1','scar':'L','ak74':'M','abrams':'M1A2','leopard':'2A7','ariete':'C1','leclerc':'XLR','challenger':'2','t90':'M','arjun':'Mk1A','centurion':'Mk 3','challenger1':'1','f16':'Block 70','f35':'A','f15':'EX','rafale':'C','gripen':'E','su35':'S','superhornet':'E','growler':'G','c130':'J','p8':'A','ohio':'SSGN'}.get(id,''),'navalClass':name if group=='naval' else None},'game':game,'provenance':{'url':sources[lookup.get(id,id)],'checkedAt':'2026-10-30','status':'verifica parziale' if id in partial else 'nome e ruolo documentati','scope':'Identificazione e ruolo; valori numerici esclusivamente di gioco.','pendingFields':['Conferma puntuale di produttore, origine e configurazione'] if id in partial else []},'photo':None,'photoStatus':'Foto non disponibile'})
# Preserve stable IDs (especially b52) and all unrelated balance values.
strategic=json.loads((root/'src/simple/strategic-bombers.json').read_text())
for item in strategic['models']:
 existing=next((row for row in rows if row['id']==item['id']),None)
 if existing is None:
  rows.append({**item,'photo':None,'photoStatus':'Foto non disponibile'})
 else:
  existing.update(item)
assert len(rows)==66 and len({r['id'] for r in rows})==66
if (root/'src/simple/photos.json').exists():
 photos={}
 for filename in ['photos.json','photos-ground.json','photos-airsea.json','photos-civil.json','photos-extra.json','photos-bombers.json']:
  file=root/'src/simple'/filename
  if file.exists():photos.update(json.loads(file.read_text()))
 for row in rows:
  if row['id'] in photos:row['photo']=photos[row['id']];row['photoStatus']='Fotografia verificata'
(root/'src/simple/catalog.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
print(f'{len(rows)} records; 15 infantry, 15 tanks, 21 aircraft (2 strategic bombers), 15 naval classes')
